#!/usr/bin/env node
// DIG-63 (review round 2) — prune stale generated Next.js type artifacts
// before `tsc --noEmit`.
//
// tsconfig.json includes `.next/types/**/*.ts` and `.next-dev/types/**/*.ts`
// (the Next.js-recommended setup). Those files are REGENERATED by
// `next dev` / `next build` and import route modules by relative path —
// e.g. `.next/types/app/api/calendar/ics/route.ts` does
// `import * as entry from '../../../../../../src/app/api/calendar/ics/route.js'`.
// On a shared checkout (several swarm sessions, review rounds) the artifacts
// can outlive the tree they were generated from: a branch switch/reset, or a
// gate run against another ref, leaves `tsc` reading generated imports for
// routes that the current checkout does not contain. Observed verbatim in
// the DIG-63 review round:
//
//   GATES: lint=pass typecheck=fail
//   .next/types/app/api/calendar/ics/route.ts(2,24): error TS2307:
//     Cannot find module '../../../../../../src/app/api/calendar/ics/route.js' …
//   .next/types/validator.ts(233,39): error TS2307: …
//
// Reproduced 1:1 with a stale `.next` on a checkout without that route —
// while the DIG-63 branch itself typechecks clean. So the fix is to make the
// standalone `tsc` gate tree-relative only: remove the generated type dirs
// right before `tsc --noEmit` (wired as the first step of the `typecheck`
// script). Nothing else under `.next` is touched — build/dev caches stay
// warm — and the very next gates step (`npm run build`) regenerates and
// route-validates the types from the CURRENT tree, so no validation is lost.
//
// Product-side module on purpose: scripts/swarm/ is orchestrator
// infrastructure and must stay untouched by screen/bug tasks (same policy
// as scripts/build-lock.mjs, DIG-55 round 2).

import { existsSync, rmSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Generated route-type dirs per distDir. The repo keeps two distDirs on
 * purpose (build → .next, dev → .next-dev, DIG-12) — both must be pruned.
 */
export const GENERATED_TYPE_DIRS = ['.next/types', '.next-dev/types'];

/**
 * Remove stale generated type dirs under `root`. Idempotent: missing dirs
 * are a no-op and nothing is created. Returns the rel paths that existed
 * and were removed (empty on a fresh checkout).
 */
export const cleanNextTypes = ({ root = process.cwd() } = {}) => {
  const removed = [];
  for (const rel of GENERATED_TYPE_DIRS) {
    const dir = resolve(root, rel);
    if (existsSync(dir)) {
      rmSync(dir, { recursive: true, force: true });
      removed.push(rel);
    }
  }
  return removed;
};

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (isMain) {
  // Explicit root arg keeps the module testable against a sandbox dir;
  // default is the repo root (scripts/..), like build-lock.
  const argRoot = process.argv[2];
  const root = argRoot
    ? resolve(process.cwd(), argRoot)
    : resolve(dirname(fileURLToPath(import.meta.url)), '..');
  const removed = cleanNextTypes({ root });
  console.log(
    removed.length > 0
      ? `[clean-next-types] pruned stale generated types: ${removed.join(', ')}`
      : '[clean-next-types] no stale generated types found',
  );
}
